extern "C" unsigned int strlen(const char *);
extern "C" void error(const char *, ...);
extern "C" char *strcpy(char *, const char *);
struct string_buf { unsigned long long *data; int ref_count, char_length, block_length, max_blocks; };
class stringx { friend stringx operator+(const stringx &, const stringx &); friend stringx operator+(const stringx &, const char *); protected: char *chars; string_buf *my_buf; public: stringx(); stringx(const stringx &); stringx(const char *, int = -1); ~stringx(); void append(const char *, int = -1); void append(const stringx &); void make_room(int); const char *c_str() const { return chars; } };
inline stringx operator+(const stringx &lhs, const stringx &rhs) { stringx foo; foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length); foo.append(lhs); foo.append(rhs); return foo; }
inline stringx operator+(const stringx &lhs, const char *rhs) { stringx foo; int len = strlen(rhs); foo.make_room(len + lhs.my_buf->char_length); foo.append(lhs); foo.append(rhs, len); return foo; }
class chunk_flavor { char flavor[16]; public: chunk_flavor(const char *text) { strcpy(flavor, text); } bool operator==(const chunk_flavor &) const; stringx to_stringx() const; };
class chunk_file { public: stringx get_name() const; };
typedef unsigned short wedge_ref; typedef short material_ref;
class face { public: wedge_ref wedge_refs[3]; material_ref my_material; unsigned short level_of_detail; unsigned short flags; };
extern chunk_flavor CHUNK_FACE_WITH_FLAGS; extern chunk_flavor CHUNK_PROGRESSIVE_FACE; extern chunk_flavor CHUNK_END;
void serial_in(chunk_file &, unsigned short *); void serial_in(chunk_file &, int *); void serial_in(chunk_file &, chunk_flavor *);
